debug_text.text:
'PS1|%s|%s|%s|%s|coord|id=%s|tclass=%s|tdist=%s|tspeed=%s|foes=%s|ffast=%s|group=%s|power=%s|ospeed=%s|ratio=%s|peers=%s|pidle=%s|pbusy=%s|psame=%s|pnear=%s|why=%s|rule=%s|cratio=%s|helpers=%s|snear=%s|ncratio=%s|policy=%s|src=%s|rall=%s|go=%s|rej=%s|far=%s'.[
              player.age, $psF.debugname, $psF.class, @$psF.sector.debugname,
              $psT.debugname, $psT.class, @$psDist,
              if $psV900 and @$psT.unboostedmaxspeed != null then @$psT.unboostedmaxspeed else @$psT.maxspeed,
              @$psFoes, @$psFast, @$psGroup, @$psPower,
              if $psV900 and @$psF.unboostedmaxspeed != null then @$psF.unboostedmaxspeed else @$psF.maxspeed,
              @$psRatio, @$psPeersN, @$psIdleN, @$psBusyN, @$psOthers, @$psNearAny, @$psWhy, @$psRule,
              if @$psGroup gt 0 then $psCommitted / $psGroup else -1, @$psHelpers.count, @$psSameNear,
              if @$psGroup gt 0 then $psCommittedNear / $psGroup else -1,
              if $psPolicy then 'on' else 'off', @$psSrc, @$psRatioAll, @$psGo.count, @$psRej, if @$psFarUsed then 1 else 0
            ]
